export const BODY: string = "\n<p>پانچ سو کلو بائٹ اور ایک میگا بائٹ سننے میں بہت مختلف لگتے ہیں۔ ایک دوسرے سے آدھا ہے، تو بڑی فائل دو گنا بہتر لگنی چاہیے، ہے نا؟</p>\n<p>بالکل ایسا نہیں ہے۔ تصویر کی کوالٹی فائل سائز کے ساتھ سیدھی لکیر میں نہیں بڑھتی، اور 500KB اور 1MB کے درمیان فرق نمبروں سے کہیں چھوٹا ہوتا ہے۔</p>\n<p>اس موازنے میں بتایا گیا ہے کہ ہر سائز واقعی کیا دیتا ہے، فرق کہاں چھپا ہوتا ہے، اور ویب اور پرنٹ کے لیے ان میں سے کون سا چنیں۔</p>\n<h2 id=\"short-answer\">مختصر جواب</h2>\n<p>ویب کے لیے 500KB تقریباً ہمیشہ کافی ہوتا ہے۔ 1MB تصویر اسکرین پر بمشکل بہتر لگتی ہے، مگر وہ دو گنا آہستہ لوڈ ہوتی ہے۔</p>\n<p>پرنٹ کے لیے دونوں سائز مثالی نہیں۔ پرنٹ کو اعلیٰ ریزولوشن والے اصل چاہیے ہوتے ہیں، اور 500KB اور 1MB دونوں شیئرنگ کے سائز ہیں، پرنٹ کے نہیں۔</p>\n<p>جب تصویر اسکرین پر دیکھی جائے گی تو 500KB استعمال کریں۔ 1MB صرف تب استعمال کریں جب کوئی سسٹم خاص طور پر مانگے یا تصویر غیر معمولی طور پر تفصیل دار ہو۔</p>\n<p>اضافی 500KB بہت کم دکھائی دینے والی کوالٹی خریدتا ہے۔ اسے صرف تب خرچ کریں جب آپ کے پاس ٹھوس وجہ ہو، عادت سے نہیں۔</p>\n<h2 id=\"what-500kb-looks-like\">500KB کیسی لگتی ہے</h2>\n<p>500KB پر تصویر اصل جیسی ہی لگتی ہے۔ باریک تفصیل، ہموار گریڈینٹ اور تیز متن سب بچ جاتے ہیں۔</p>\n<p>پورٹریٹ میں جلد کے قدرتی رنگ اور بالوں کی بناوٹ برقرار رہتی ہے۔ لینڈ اسکیپ میں دور کی تفصیل بچتی ہے جسے چھوٹے سائز چپٹا کر دیتے ہیں۔</p>\n<p>اسکرین شاٹس اور انفوگرافکس میں متن پڑھنے کے قابل رہتا ہے۔ چھوٹے لیبل جو 100KB پر دھندلے ہو جاتے ہیں، 500KB پر صاف رہتے ہیں۔</p>\n<p>زیادہ تر ناظرین کے لیے، زیادہ تر اسکرینوں پر، 500KB تصویر بغیر کمپریس شدہ اصل سے الگ نہیں پہچانی جا سکتی۔</p>\n<h2 id=\"what-1mb-looks-like\">1MB کیسی لگتی ہے</h2>\n<p>1MB پر تصویر 500KB سے بھی زیادہ تفصیل رکھتی ہے۔ فرق حقیقی ہے، مگر یہ صرف قریب سے دیکھنے پر نظر آتا ہے۔</p>\n<p>200 فیصد زوم کریں اور دونوں کا موازنہ کریں۔ 1MB ورژن بالوں، کپڑے اور پتوں میں کچھ زیادہ بناوٹ رکھتا ہے۔</p>\n<p>عام دیکھنے کے سائز پر دونوں ایک جیسی لگتی ہیں۔ اضافی ڈیٹا وہ تفصیل محفوظ کرتا ہے جسے آنکھ زوم کیے بغیر حل ہی نہیں کر سکتی۔</p>\n<p>گریڈینٹ وہ ایک جگہ ہے جہاں 1MB واضح مدد کرتا ہے۔ ہموار آسمان میں 1MB پر 500KB سے معمولی کم بینڈنگ نظر آتی ہے۔</p>\n<h2 id=\"side-by-side\">آمنے سامنے: ایک ہی تصویر دونوں سائز میں</h2>\n<p>ایک پورٹریٹ لیں۔ 500KB پر چہرہ تیز ہے، بالوں میں بناوٹ ہے اور پس منظر ہموار ہے۔</p>\n<p>اسی پورٹریٹ کو 1MB پر عام سائز میں دیکھیں تو وہ ایک جیسی لگتی ہے۔ قریب زوم کریں تو بالوں میں چند انفرادی لٹیں زیادہ نظر آتی ہیں۔</p>\n<p>ایک لینڈ اسکیپ لیں۔ 500KB پر دور کے درخت صاف ہیں اور آسمان ہموار ہے۔ 1MB پر درختوں میں پتوں کی کچھ زیادہ تفصیل نظر آتی ہے۔</p>\n<p>ایک اسکرین شاٹ لیں۔ دونوں سائز میں متن صاف اور پڑھنے کے قابل ہے۔ ان کے درمیان فرق بنیادی طور پر نظر نہیں آتا۔</p>\n<p>پیٹرن مستقل ہے: 1MB صرف بڑا کر کے دیکھنے پر جیتتا ہے۔ جن سائز میں تصاویر واقعی دیکھی جاتی ہیں، ان میں 500KB اس کے برابر ہے۔</p>\n<h2 id=\"loading-speed\">لوڈنگ رفتار: جہاں 500KB واضح جیتتی ہے</h2>\n<p>لوڈنگ رفتار وہ جگہ ہے جہاں سائز واقعی مختلف ہوتے ہیں۔ کسی بھی کنکشن پر 1MB تصویر ڈاؤن لوڈ ہونے میں 500KB سے دو گنا وقت لیتی ہے۔</p>\n<p>تیز کنکشن پر فرق سیکنڈ کا حصہ ہوتا ہے۔ سست موبائل کنکشن پر یہ کئی سیکنڈ ہو سکتا ہے۔</p>\n<p>صفحات میں بہت سی تصاویر ہوتی ہیں۔ دس تصاویر 1MB پر 10MB بنتی ہیں، جبکہ 500KB پر 5MB، اور فرق ہر تصویر کے ساتھ بڑھتا ہے۔</p>\n<p>ناظرین سست صفحات چھوڑ دیتے ہیں۔ دو سیکنڈ میں لوڈ ہونے والی گیلری قارئین کو روکتی ہے، جبکہ وہی گیلری آٹھ سیکنڈ میں انہیں کھو دیتی ہے۔</p>\n<p>چند تصاویر سے زیادہ والے کسی بھی صفحے کے لیے 500KB بہتر انتخاب ہے۔ کوالٹی کی قیمت نظر نہیں آتی اور رفتار کا فائدہ حقیقی ہوتا ہے۔</p>\n<h2 id=\"when-1mb-wins\">جب 1MB واقعی جیتتا ہے</h2>\n<p>بہت تفصیل والی تصاویر کو 1MB سے فائدہ ہوتا ہے۔ گھنی بھیڑ کا منظر، جنگل کی چھت یا پیچیدہ تصویر بڑے سائز میں زیادہ تفصیل رکھتی ہے۔</p>\n<p>جن تصاویر کو بعد میں کراپ کرنا ہو انہیں 1MB چاہیے ہوتا ہے۔ کراپ پکسل پھینک دیتا ہے، اس لیے بڑے سے شروع کرنے پر کراپ کے بعد زیادہ تفصیل بچتی ہے۔</p>\n<p>بہت بڑی دکھائی جانے والی تصاویر کو بھی فائدہ ہوتا ہے۔ بڑے مانیٹر پر پورے اسکرین کا ہیرو چھوٹے تھمب نیل سے زیادہ فرق دکھاتا ہے۔</p>\n<p>کچھ پلیٹفارم کور تصاویر کے لیے 1MB کم از کم مانگتے ہیں۔ جب اصول مانگیں تو انتخاب آپ کے لیے ہو جاتا ہے۔</p>\n<p>ان صورتوں کے باہر 1MB اکثر ضرورت سے زیادہ ہوتا ہے۔ بینڈوڈتھ بچائیں اور اس کے بجائے 500KB استعمال کریں۔</p>\n<h2 id=\"print-reality\">پرنٹ کی حقیقت: کوئی بھی سائز کافی نہیں</h2>\n<p>پرنٹ کو تقریباً 300 پکسل فی انچ چاہیے ہوتے ہیں۔ 8 بائی 10 انچ پر چھپنے والی تصویر کو 2400 بائی 3000 پکسل چاہیے، جو 500KB یا 1MB میں شاذ و نادر ہی آتے ہیں۔</p>\n<p>500KB فائل چھوٹے سائز پر صاف چھپتی ہے، جیسے پاسپورٹ تصویر یا پوسٹ کارڈ۔ بڑے پرنٹ نرم لگیں گے۔</p>\n<p>1MB فائل کچھ بڑی چھپتی ہے، مگر پھر بھی بڑی نہیں۔ یہ 5 بائی 7 انچ پرنٹ اچھا سنبھالتی ہے اور اس سے آگے مشکل ہوتی ہے۔</p>\n<p>حقیقی پرنٹ کام کے لیے اصل فائل رکھیں۔ 10MB ماسٹر کسی بھی مناسب سائز پر خوبصورتی سے چھپتا ہے، جبکہ کمپریس شدہ کاپیاں نہیں چھپتیں۔</p>\n<p>500KB اور 1MB کو اسکرین سائز سمجھیں۔ یہ دیکھنے کے لیے ہیں، چھاپنے کے لیے نہیں، اور اصل کاغذ کے لیے ہے۔</p>\n<h2 id=\"format-effects\">فارمیٹ موازنے کو کیسے بدلتا ہے</h2>\n<p>JPG دونوں سائز میں سب سے محفوظ فارمیٹ ہے۔ یہ ہر جگہ قبول ہوتا ہے، اور 500KB اور 1MB پر تصاویر کے لیے اس کی کوالٹی بہترین ہوتی ہے۔</p>\n<p>WebP اکثر ایک ہی سائز پر JPG سے کچھ بہتر ہوتا ہے۔ 500KB پر WebP تصویر 1MB JPG کے برابر ہو سکتی ہے، جس سے موازنہ 500KB کے حق میں اور بھی بہتر ہو جاتا ہے۔</p>\n<p>PNG گرافکس کے لیے موزوں ہے، تصاویر کے لیے نہیں۔ چارٹ یا لوگو PNG میں پکسل پرفیکٹ رہتا ہے، مگر PNG میں تصویر دونوں سائز پر بجٹ ضائع کرتی ہے۔</p>\n<p>عملی اصول سادہ ہے: مطابقت کے لیے JPG، جدید پلیٹفارمز پر تیز ترین نتیجے کے لیے WebP۔</p>\n<h2 id=\"decision-framework\">فیصلے کا ڈھانچہ</h2>\n<p>پہلے اصول چیک کریں۔ اگر پلیٹفارم نے سائز بتایا ہو تو وہی سائز فیصلہ کرتا ہے، اور بحث ختم ہو جاتی ہے۔</p>\n<p>دوسرے، تصاویر گنیں۔ ایک ہیرو تصویر 1MB ہو سکتی ہے، مگر بیس گیلری تصاویر 500KB یا اس سے چھوٹی ہونی چاہیے۔</p>\n<p>تیسرے، مواد پر غور کریں۔ متن والی تصاویر اور تفصیل والے مناظر کو سادہ پورٹریٹ سے زیادہ 1MB سے فائدہ ہوتا ہے۔</p>\n<p>چوتھے، سامعین پر غور کریں۔ سست کنکشن والے موبائل صارفین 500KB کے لیے شکر گزار ہوں گے، جبکہ ڈیسک ٹاپ صارفین فرق محسوس نہیں کریں گے۔</p>\n<p>شک ہو تو 500KB استعمال کریں۔ یہ محفوظ ڈیفالٹ ہے، اور آپ کسی خاص تصویر کے لیے ہمیشہ بڑا سائز لے سکتے ہیں جسے ضرورت ہو۔</p>\n<h2 id=\"testing-yourself\">فرق خود کیسے آزمائیں</h2>\n<p>اپنی سب سے تفصیل والی تصویر چنیں، سب سے آسان والی نہیں۔ مصروف لینڈ اسکیپ وہ فرق دکھائے گا جو سادہ پورٹریٹ چھپاتا ہے۔</p>\n<p>اسے <a href=\"/ur/tasveer-compress-karein-500kb-tak/\">500KB کمپریسر</a> سے 500KB تک کمپریس کریں۔ پھر اسی تصویر کو <a href=\"/ur/makhsus-size-tak-tasveer-compress-karein/\">target file size compressor</a> سے 1024KB پر سیٹ کر کے 1MB تک کمپریس کریں۔</p>\n<p>دونوں کو اسی اسکرین پر پورے سائز میں دیکھیں جہاں تصویر دکھائی جائے گی۔ ہر ورژن میں ایک ہی جگہوں کا موازنہ کریں۔</p>\n<p>200 فیصد زوم کریں اور دوبارہ دیکھیں۔ یہیں 1MB کا فائدہ ظاہر ہوتا ہے، اگر ظاہر ہو تو۔</p>\n<p>پھر دونوں کو عام سائز میں ایک آخری بار دیکھیں۔ اگر آپ انہیں الگ نہ پہچان سکیں تو فیصلہ ہو گیا: 500KB استعمال کریں۔</p>\n<h2 id=\"banding-compared\">500KB بمقابلہ 1MB پر رنگ بینڈنگ</h2>\n<p>رنگ بینڈنگ ہموار جگہوں، جیسے آسمان یا سادہ دیواروں، میں نظر آنے والی پٹیوں کے طور پر ظاہر ہوتی ہے۔ یہ کمپریس شدہ تصاویر میں سب سے عام بصری خرابی ہے۔</p>\n<p>500KB پر بینڈنگ شاذ و نادر ہوتی ہے مگر بہت ہموار گریڈینٹ میں ممکن ہے۔ غروبِ آفتاب کا آسمان غور سے دیکھیں تو ہلکے قدم دکھا سکتا ہے۔</p>\n<p>1MB پر بینڈنگ تقریباً غائب ہو جاتی ہے۔ اضافی ڈیٹا گریڈینٹ کو باریک قدموں میں بیان کرتا ہے، اس لیے منتقلی ہموار لگتی ہے۔</p>\n<p>زیادہ تر تصاویر کے لیے فرق نظر نہیں آتا۔ صرف بڑے، ہموار گریڈینٹ اچھی اسکرین پر دیکھنے سے یہ ظاہر ہوتا ہے۔</p>\n<p>اگر بینڈنگ پریشان کرے تو پہلے 500KB پر WebP آؤٹ پٹ آزمائیں۔ یہ JPG سے کچھ بہتر گریڈینٹ سنبھالتا ہے، اور اکثر 1MB سے فرق مکمل ختم کر دیتا ہے۔</p>\n<h2 id=\"cropping-future\">بعد میں کراپ کرنا: شروع کا سائز کیوں اہمیت رکھتا ہے</h2>\n<p>کراپ پکسل پھینک دیتا ہے، اس لیے شروع کا سائز طے کرتا ہے کہ کراپ کے بعد کتنی تفصیل بچتی ہے۔ 1MB تصویر بھاری کراپ 500KB سے بہتر برداشت کرتی ہے۔</p>\n<p>اگر آپ تصویر کو تفصیل والے شاٹ میں کراپ کرنے کا ارادہ رکھتے ہیں تو 1MB ورژن رکھیں۔ اضافی ڈیٹا آپ کو کاٹنے کی گنجائش دیتا ہے بغیر نتیجہ بکھرنے کے۔</p>\n<p>جو تصاویر جیسی ہیں ویسی ہی استعمال ہوں گی ان کے لیے 500KB کافی ہے۔ کراپ نہ ہونے کا مطلب ہے فائل پر کوئی اضافی مطالبہ نہیں۔</p>\n<p>شک ہو تو اصل رکھیں۔ اصل کسی بھی کراپ سے بچ جاتا ہے، جبکہ ہر کمپریس شدہ کاپی ایک سمجھوتا ہوتی ہے۔</p>\n<p>پہلے سوچیں کہ تصویر کیسے استعمال ہو گی۔ جو تصویر تنگ کراپ کے لیے مقدر ہو اسے بڑی فائل ملنی چاہیے، جو پوری دکھائی جائے اسے نہیں۔</p>\n<h2 id=\"hero-images\">ہیرو تصاویر: وہ ایک جگہ جہاں 1MB معنی رکھتا ہے</h2>\n<p>ہیرو تصویر پورا اسکرین بھرتی ہے، اس لیے ہر خامی نظر آتی ہے۔ یہ وہ ایک جگہ ہے جہاں 1MB اپنا اضافی وزن کماتا ہے۔</p>\n<p>ہیرو تصاویر عام طور پر اکیلی دکھائی جاتی ہیں، اس لیے صفحے پر صرف ایک بڑی فائل ہوتی ہے۔ لوڈنگ کی قیمت کم اور کوالٹی کا فائدہ نظر آنے والا ہوتا ہے۔</p>\n<p>بڑے مانیٹرز پر 1MB ہیرو تیز رہتا ہے جہاں 500KB کچھ نرم ہو سکتا ہے۔ پورے اسکرین پر فرق معمولی مگر حقیقی ہوتا ہے۔</p>\n<p>فون پر فرق غائب ہو جاتا ہے۔ فون کی چوڑائی پر دکھایا گیا ہیرو کہیں کم ڈیٹا چاہتا ہے، اس لیے وہاں 500KB کافی ہوتا ہے۔</p>\n<p>مختلف اسکرینوں کے لیے مختلف سائز دینے پر غور کریں۔ ڈیسک ٹاپ کے لیے 1MB ہیرو اور موبائل کے لیے 500KB ہیرو ہر ناظر کو درست فائل دیتا ہے۔</p>\n<h2 id=\"galleries-compared\">گیلریز: جہاں 500KB ہر بار جیتتا ہے</h2>\n<p>گیلریز میں بہت سی تصاویر ہوتی ہیں، اور کل وزن لوڈنگ وقت طے کرتا ہے۔ بیس تصاویر 1MB پر 20MB بنتی ہیں، جو کہیں زیادہ بھاری ہے۔</p>\n<p>وہی گیلری 500KB پر 10MB بنتی ہے، جو پھر بھی بھاری ہے۔ بہت سی گیلریز اسی وجہ سے فی تصویر 200KB استعمال کرتی ہیں۔</p>\n<p>ناظرین گیلریز کو تیزی سے دیکھتے ہیں، ہر تصویر پر سیکنڈ گزارتے ہیں۔ اس رفتار پر وہ 500KB اور 1MB کے درمیان فرق محسوس نہیں کریں گے۔</p>\n<p>گیلری میں نمایاں تصویر کے لیے 500KB اور باقی کے لیے چھوٹے سائز استعمال کریں۔ یہ توازن صفحے کو تیز رکھتا ہے بغیر شوکیس شاٹ کو نقصان پہنچائے۔</p>\n<p>شائع کرنے کے بعد گیلری کا لوڈ وقت ناپیں۔ اگر یہ سست لگے تو تصاویر سب سے پہلی چیز ہیں جنہیں چھوٹا کرنا چاہیے۔</p>\n<h2 id=\"email-attachments\">500KB بمقابلہ 1MB پر ای میل اٹیچمنٹ</h2>\n<p>ای میل سسٹم اٹیچمنٹ کو محدود کرتے ہیں، اکثر فی پیغام 20MB یا 25MB تک۔ 1MB تصاویر کا سیٹ اس بجٹ کو 500KB والوں سے دو گنا تیزی سے کھاتا ہے۔</p>\n<p>کلائنٹ پروف کے لیے 500KB تصاویر اسکرین پر 1MB جیسی ہی لگتی ہیں۔ کلائنٹ کام کو واضح دیکھتا ہے بغیر بڑے ڈاؤن لوڈ کا انتظار کیے۔</p>\n<p>ایک تصویر کے لیے فرق اہمیت نہیں رکھتا۔ ایک 1MB اٹیچمنٹ اتنی ہی آسانی سے بھیجی جاتی ہے جتنی ایک 500KB اٹیچمنٹ۔</p>\n<p>دس یا بیس تصاویر کے سیٹ کے لیے 500KB بہتر انتخاب ہے۔ ای میل ہلکی رہتی ہے اور وصول کنندہ اسے تیزی سے کھول سکتا ہے۔</p>\n<p>پرنٹ کے لیے اصل بھیجتے وقت بالکل کمپریس نہ کریں۔ فائل شیئرنگ لنک کے ذریعے پوری ریزولوشن والی فائل بھیجیں، ای میل کے بجائے۔</p>\n<h2 id=\"storage-costs\">اسٹوریج اور بینڈوڈتھ کے اخراجات</h2>\n<p>ہر کلو بائٹ جو محفوظ یا پیش کیا جاتا ہے اس کی قیمت ہوتی ہے، چاہے وہ چھپی ہو۔ ہزاروں 1MB تصاویر والی سائٹ اسٹوریج کے لیے اسی سائٹ سے دو گنا زیادہ ادا کرتی ہے جو 500KB پر ہو۔</p>\n<p>بینڈوڈتھ اسٹوریج سے زیادہ اہمیت رکھتی ہے۔ ہر ناظر ہر تصویر جو وہ دیکھتا ہے ڈاؤن لوڈ کرتا ہے، اس لیے 1MB تصاویر والا مقبول صفحہ پیش کرنے میں کہیں زیادہ مہنگا پڑتا ہے۔</p>\n<p>چھوٹی ذاتی سائٹ کے لیے قیمت معمولی ہوتی ہے۔ مصروف دکان یا گیلری کے لیے 500KB اور 1MB کے درمیان فرق سال بھر میں نمایاں ہو سکتا ہے۔</p>\n<p>چھوٹی فائلوں کا مطلب تیز بیک اپ بھی ہے۔ فی تصویر 500KB والی میڈیا لائبریری 1MB والی اسی لائبریری سے آدھے وقت میں بیک اپ ہوتی ہے۔</p>\n<p>یہ اخراجات اس وقت تک نظر نہیں آتے جب تک وہ ظاہر نہ ہو جائیں۔ 500KB کو ڈیفالٹ چننا انہیں کم رکھتا ہے بغیر کسی دکھائی دینے والی کوالٹی قیمت کے۔</p>\n<h2 id=\"final-verdict\">آخری فیصلہ</h2>\n<p>اسکرین پر دیکھنے کے لیے 500KB جیتتا ہے۔ یہ دکھائی دینے والی کوالٹی میں 1MB کے برابر ہے، دو گنا تیزی سے لوڈ ہوتا ہے، اور محفوظ کرنے اور پیش کرنے میں آدھی قیمت لیتا ہے۔</p>\n<p>پرنٹ کے لیے کوئی نہیں جیتتا۔ دونوں اسکرین سائز ہیں، اور حقیقی پرنٹ کام کو اصل اعلیٰ ریزولوشن فائل چاہیے ہوتی ہے۔</p>\n<p>بھاری کراپ یا پورے اسکرین ہیرو جیسے خاص معاملات کے لیے 1MB اپنی جگہ کماتا ہے۔ اسے وہاں استعمال کریں، اور ہر جگہ اور 500KB استعمال کریں۔</p>\n<p>سب سے دانشمندانہ طریقہ یہ ہے کہ اصل رکھیں اور ہر کام کے لیے درست سائز بنائیں۔ لچکدار ورک فلو ہر بار ایک فکسڈ سائز سے بہتر ہوتا ہے۔</p>\n<p>500KB سے شروع کریں، نتیجہ آزمائیں، اور صرف تب بڑا جائیں جب آپ کی آنکھیں بتائیں کہ ضرورت ہے۔ زیادہ تر وقت وہ نہیں بتائیں گی۔</p>\n<ul>\n<li>تیز سائٹ پر ایک ہیرو تصویر: 1MB ٹھیک ہے۔</li>\n<li>بہت سی تصاویر والی گیلری یا بلاگ: 500KB۔</li>\n<li>موبائل سامعین: ہمیشہ 500KB۔</li>\n<li>پرنٹ کام: اصل رکھیں، کوئی بھی سائز کافی نہیں۔</li>\n<li>تفصیل والی تصویر جسے کراپ کرنا ہو: 1MB۔</li>\n</ul>\n<p>مکمل 500KB گائیڈ کے لیے <a href=\"/ur/blog/tasveer-500kb-tak-compress-karein-rehnumai/\">Compress Image to 500KB: Complete Guide</a> پڑھیں۔ عملی مراحل کے لیے <a href=\"/ur/blog/tasveer-500kb-tak-kaise-compress-karein/\">How to Compress an Image to 500KB</a> دیکھیں۔ چھوٹے سائز کے لیے <a href=\"/ur/tasveer-compress-karein-200kb-tak/\">200KB کمپریسر</a> استعمال کریں۔</p>\n";

